import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0050: Map zoom and connector motion","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0050-map-zoom-and-connector-motion.md","filePath":"adrs/0050-map-zoom-and-connector-motion.md","lastUpdated":1789092097000}`),a={name:`adrs/0050-map-zoom-and-connector-motion.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0050-map-zoom-and-connector-motion" tabindex="-1">ADR-0050: Map zoom and connector motion <a class="header-anchor" href="#adr-0050-map-zoom-and-connector-motion" aria-label="Permalink to “ADR-0050: Map zoom and connector motion”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-06 · Refines <a href="/adrs/0047-native-graph-controls-and-session-charts">ADR-0047</a> and <a href="/adrs/0049-native-map-input-ownership">ADR-0049</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The 500% camera ceiling prevented close inspection. Accelerated wheel events could zoom sharply, and the fixed pan bound could displace the pointer anchor at higher zoom. Selected record actions also blended into the legend. The renderer replacement had removed connector motion.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The shared camera supports 20–2000% zoom. Trackpad pixels and mouse wheel lines have separate sensitivities, with each event bounded before exponentiation. Pan bounds grow with zoom, preserving pointer anchoring during close inspection. Toolbar, keyboard, and pinch use the same camera limits. Fit resets zoom, position, and orbit.</p><p>An isolated Canvas overlay draws up to 24 moving connector dots at a maximum of 30 frames per second. Projected paths are prepared outside the ticking subtree; static topology, labels, native input, and accessibility targets do not depend on the animation clock. Dots follow the exact quadratic connector paths and focus narrows them to incident links. They are decorative relationship tracers, not evidence of live data transfer or causal direction. Motion runs only while the map owns interaction and its scene is active, respects Reduce Motion and the interface animation setting, and can be disabled with Animate connections. It performs no layout or network work per frame.</p><p>The badge says Map active, the search field says Search, and the selected record uses a tinted, bordered card with a divider before the legend.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Scroll bursts cannot overflow the exponential scale or jump directly to an extreme.</li><li>Camera tests cover gradual input, reversibility, bounds, invalid input, and high-zoom anchoring.</li><li>Motion stops when the user leaves the map and introduces no dependency or background polling.</li><li>Live checks still cover native input and presentation, beyond the camera&#39;s unit tests.</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};